+/// Итог в копейках. Скидка целыми процентами, как в прайсе клиники.
+pub fn total(positions: &[Position], discount_percent: u8) -> i32 {
+    let mut sum: i32 = 0;
+
+    for p in positions {
+        sum += p.kop * p.qty as i32;
+    }
+
+    let discount = sum / 100 * discount_percent as i32;
+
+    sum - discount
 }

 pub fn format(kop: i32) -> String {
     format!("{},{:02} ₽", kop / 100, kop % 100)
 }
